  /* landing: features */
  'المميزات': 'Features',
  'كل ما تحتاجه في مكان واحد': 'Everything you need in one place',
  'صُمّم خصيصاً لعيادات الأسنان في السوق السوري': 'Designed specifically for dental clinics in the Syrian market',
  'مدعوم بالذكاء الاصطناعي في كل خطوة': 'AI-powered at every step',
  'يتقن العربية ويعمل داخل المنصة: يلخّص ملف المريض قبل الجلوس على الكرسي، ويشرح خطة العلاج بلغة المريض، ويصيغ رسائل الاستدعاء والتعليمات، ويلخّص حسابات عيادتك — وميزات أخرى تكتشفها مع أول أسبوع استخدام. كل مخرجاته قابلة للتعديل، واسم المريض لا يغادر متصفّحك، والقرار النهائي لك.': "Fluent in Arabic and built into the platform: it summarises the patient file before the patient sits in the chair, explains the treatment plan in the patient's language, drafts recall messages and instructions, and summarises your clinic's accounts — plus more you will discover in your first week. Everything it writes can be edited, the patient's name never leaves your browser, and the final decision is always yours.",
  'بوابة المريض': 'Patient portal',
  'رابط شخصي لكل مريض يفتحه من هاتفه بلا حساب ولا كلمة سر: يرى مواعيده القادمة ويؤكّدها، ويطلب إلغاءها أو تغيير وقتها، ويتابع خطة علاجه ورصيده وأقساطه، وتعليماتك وروشتاته، وصور الأشعة التي تختار مشاركتها، ويملأ استمارة التاريخ الطبي قبل زيارته. وأنت تحدّد ما يظهر له.': 'A personal link for each patient, opened from their phone with no account or password: they see and confirm upcoming appointments, ask to cancel or reschedule, follow their treatment plan, balance and instalments, your instructions and prescriptions, the X-rays you choose to share, and fill in the medical history form before their visit. You decide what they see.',
  'محاسبة عيادة احترافية': 'Professional clinic accounting',
  'يفصل الإنتاج عن التحصيل عن صافي الربح كما يفعل المحاسب المحترف: ذمم كل مريض، مستحقات كل طبيب، المصاريف وتكاليف المخبر، والدفعة المقدّمة تبقى أمانة حتى يكتمل العلاج. وإن كنت تعمل بالليرة والدولار، فلكل عملة حسابها المستقلّ بلا خلط. كل ليرة لها مصدر ومسار — بلا Excel جانبي.': "Separates production, collections and net profit the way a professional accountant does: each patient's balance, each doctor's dues, expenses and lab costs, and a down payment stays held until the treatment is complete. If you work in both pounds and dollars, each currency keeps its own separate account with no mixing. Every pound has a source and a trail — no side spreadsheet.",
  'إدارة المرضى': 'Patient management',
  'سجلات كاملة لكل مريض — مخطط أسنان تفاعلي، مخطط لثة، خطة علاج مرحلية، وتاريخ علاجي موثّق. لديك مرضاك في ملف Excel؟ ارفعه بضغطة — وصدِّرهم بضغطة متى شئت. بياناتك تبقى ملكك.': 'Complete records for every patient — an interactive dental chart, a periodontal chart, a phased treatment plan and a documented treatment history. Have your patients in an Excel file? Upload it in one click — and export them in one click whenever you like. Your data stays yours.',
  'تقويم المواعيد': 'Appointment calendar',
  'عرض يومي وأسبوعي وشهري مع إشعارات تلقائية. المريض طلب التأجيل؟ اسحب موعده إلى وقته الجديد — بلا إعادة إدخال ولا نوافذ، والتغيير يُسجَّل تلقائياً.': 'Day, week and month views with automatic notifications. A patient asked to reschedule? Drag the appointment to its new time — no re-entry, no pop-ups, and the change is logged automatically.',
  'بوابة حجز إلكترونية': 'Online booking page',
  'رابط خاص بعيادتك يحجز منه مرضاك بأنفسهم — وتصلك الطلبات مرتّبة لتأكيدها بنقرة واحدة.': 'A link for your clinic where patients book themselves — requests reach you neatly, ready to confirm in one click.',
  'تذكيرات واتساب': 'WhatsApp reminders',
  'تذكير بالمواعيد، استدعاء للمراجعة الدورية، وتهنئة بأعياد الميلاد — بقوالب جاهزة قابلة للتخصيص.': 'Appointment reminders, recall for check-ups and birthday greetings — with ready templates you can customise.',
  'مخبر ومخزون': 'Lab and inventory',
  'تتبّع طلبات المخبر وتكاليفها لكل طبيب، ومخزون بالمواد والدفعات مع تنبيهات النقص والانتهاء.': 'Track lab orders and their cost per doctor, and an inventory of materials and batches with low-stock and expiry alerts.',
  'سحابي بالكامل': 'Fully in the cloud',
  'لا حاجة للتثبيت — افتحه من الهاتف أو الحاسوب في أي مكان وأي وقت.': 'Nothing to install — open it from your phone or computer anywhere, any time.',
  'أمان وخصوصية': 'Security and privacy',
