  /* landing: FAQ + footer */
  'أسئلة شائعة': 'FAQ',
  'كل ما تريد معرفته': 'Everything you want to know',
  'وإن كان لديك سؤال آخر، تواصل معنا وسنجيبك بسرعة': "If you have another question, contact us and we'll answer quickly",
  'هل بياناتي وبيانات مرضاي آمنة؟': "Is my data and my patients' data safe?",
  'نعم. كل عيادة معزولة تماماً عن غيرها على مستوى قاعدة البيانات — لا يمكن لأي حساب الاطلاع على بيانات حساب آخر. البيانات مستضافة على بنية سحابية عالمية مع نسخ احتياطي يومي تلقائي.': "Yes. Every clinic is fully isolated from the others at the database level — no account can see another account's data. The data is hosted on global cloud infrastructure with automatic daily backups.",
  'هل أحتاج تثبيت برنامج أو خبرة تقنية؟': 'Do I need to install software or have technical skills?',
  'لا شيء إطلاقاً. SyDent يعمل من المتصفح على أي جهاز — هاتف، جهاز لوحي، أو حاسوب — بلا أي تثبيت أو خبرة تقنية. وإن أحببت، ثبّته بضغطة واحدة كتطبيق على جهازك. سجّل حسابك وابدأ خلال دقائق، والواجهة عربية بالكامل ومصمّمة لتكون بديهية.': "Nothing at all. SyDent runs in the browser on any device — phone, tablet or computer — with no installation or technical skills. If you like, install it as an app on your device in one tap. Create your account and start within minutes; the interface is designed to be intuitive and is available in Arabic and English.",
  'هل يعمل SyDent عند انقطاع الإنترنت؟': 'Does SyDent work when the internet is down?',
  'نعم — صُمّم SyDent خصيصاً ليتحمّل انقطاعات الإنترنت والكهرباء المتكرّرة. عند انقطاع الاتصال يتابع النظام عمله بشكل طبيعي: تتصفح ملفات مرضاك، وتدير مواعيدك، وتسجّل دفعات المرضى — كل ذلك بلا اتصال. وفور عودة الإنترنت، يتزامن كل شيء تلقائياً دون أن تفقد أي معلومة أو تحتاج لإعادة إدخالها.': "Yes — SyDent is built to withstand frequent internet and power cuts. When the connection drops, the system keeps working normally: you browse patient files, manage appointments and record payments — all offline. As soon as the internet is back, everything syncs automatically without losing anything or re-entering it.",
  'كيف تعمل بوابة الحجز الإلكترونية؟': 'How does the online booking page work?',
  'لكل عيادة رابط حجز خاص تشاركه مع مرضاك (واتساب، إنستغرام، بطاقة العيادة…). المريض يختار اليوم والوقت المناسبين، ويصلك الطلب داخل النظام لتأكيده أو تعديله بنقرة واحدة.': 'Every clinic has its own booking link to share with patients (WhatsApp, Instagram, the clinic card…). The patient picks a day and time, and the request reaches you in the system to confirm or adjust in one click.',
  'ما هي بوابة المريض؟': 'What is the patient portal?',
  'صفحة خاصة بكل مريض تُرسلها له برابط عبر واتساب، فيفتحها من هاتفه دون تسجيل دخول. فيها مواعيده مع زر تأكيد الحضور وطلب الإلغاء أو التغيير، وخطة علاجه، ورصيده وأقساطه، وتعليمات ما بعد العلاج والروشتات، وصور الأشعة التي تشاركها معه، واستمارة التاريخ الطبي. تختار من الإعدادات ما يظهر للمريض وهل يُسمح له بالإلغاء والتغيير، وكل ما يرسله يظهر لك أعلى صفحة المواعيد.': 'A page of their own that you send each patient as a WhatsApp link; they open it from their phone without signing in. It shows their appointments with buttons to confirm attendance or ask to cancel or reschedule, their treatment plan, balance and instalments, post-treatment instructions and prescriptions, the X-rays you share with them, and the medical history form. In settings you choose what the patient sees and whether they may cancel or reschedule, and everything they send appears at the top of your appointments page.',
  'هل يمكن لأكثر من طبيب العمل على نفس الحساب؟': 'Can more than one doctor work on the same account?',
  'نعم — أضف أطباءك وموظفيك ضمن حساب العيادة، وخصّص المواعيد والجلسات لكل طبيب، واحصل على تقارير مستحقات منفصلة لكل واحد منهم.': 'Yes — add your doctors and staff to the clinic account, assign appointments and sessions to each doctor, and get a separate dues report for each of them.',
  'هل هناك تجربة مجانية؟ وماذا بعد انتهائها؟': 'Is there a free trial? What happens after it ends?',
  'نعم، تجربة مجانية كاملة الميزات وبلا بطاقة ائتمان. وبعدها القرار لك وحدك: تكمل بالخطة التي تناسب حجم عيادتك، أو تتوقّف بلا أي التزام. وبياناتك تبقى بياناتك — تُصدِّر قائمة مرضاك إلى Excel بضغطة، وبقية بياناتك متاحة لك عند الطلب.': "Yes, a full-featured free trial with no credit card. After that the decision is yours: continue with the plan that fits your clinic, or stop with no commitment. Your data stays yours — export your patient list to Excel in one click, and the rest of your data is available on request.",
  'ماذا يحدث لبياناتي إذا أوقفت الاشتراك؟': 'What happens to my data if I stop my subscription?',
  'بياناتك تبقى محفوظة ولا تُحذف تلقائياً — بمجرد تجديد الاشتراك تعود إلى عيادتك كما تركتها. وإذا رغبت بحذف حسابك نهائياً، الخيار متاح لك من الإعدادات في أي وقت.': "Your data stays saved and is never deleted automatically — as soon as you renew, you return to your clinic as you left it. If you want to delete your account permanently, the option is in settings at any time.",
  'جاهز لتنظيم عيادتك؟': 'Ready to organise your clinic?',
  'انضم إلى أطباء الأسنان الذين بدؤوا يديرون عياداتهم بذكاء — التجربة مجانية ولا تحتاج إلى بطاقة ائتمان.': 'Join the dentists who already run their clinics smartly — the trial is free and needs no credit card.',
  '© 2026 SyDent — جميع الحقوق محفوظة': '© 2026 SyDent — All rights reserved',
