/* Text assembled from numbers at runtime. Each entry: [regex on the whitespace-collapsed text, replacement]. */
window.SyI18nPatterns = [
  [/^دفعة · (.+?) ل\.س(.*)$/, 'Payment · $1 SYP$2'],
  [/^وفّر ~(\d+)%$/, 'Save ~$1%'],
  [/^حتى (\d+) موظف$/, 'Up to $1 staff'],
  [/^حتى (\d+) مريض$/, 'Up to $1 patients'],
  [/^لمدة (\d+) يوم$/, 'for $1 days'],
  [/^(.+?) \/ شهر$/, '$1 / month'],
  [/^(.+?) \/ سنة$/, '$1 / year'],
  [/^(.+?) \/ 3 أشهر$/, '$1 / 3 months'],
  [/^≈ (.+?) \/ شهر$/, '≈ $1 / month'],
  [/^ل\.س \/ (شهر|سنة|3 أشهر)$/, function (m, u) { return 'SYP / ' + ({ 'شهر': 'month', 'سنة': 'year', '3 أشهر': '3 months' })[u]; }],
  [/^غير متاح \((.+?) · (.+?)\)$/, 'Not available ($1 · $2)'],
  [/^تُطبَّع إلى (.+)$/, 'normalised to $1']
];

