  "= مجموع أسعار جلسات الطبيب في الفترة. نسبتُه تُحسب من هذا الرقم كما هو، بلا خصم تكلفة المخبر وبغضّ النظر عمّا قبضه المريض فعلاً.": "= the total price of the dentist's sessions in the period. Their share is calculated from this figure as is, without deducting lab cost and regardless of what the patient actually paid.",
