  "الاحتفاظ: كم مريضاً نشطاً لدينا، وهل يزداد العدد أم يتناقص — ومن فقدنا، ومن غادر بلا موعد قادم": "Retention: how many active patients we have, whether that's growing or shrinking — who we lost, and who left without a next appointment",
