  "الكلفة = الكمية المستهلكة × سعر الشراء المسجّل للمادة، بعملة المادة.": "Cost = quantity used × the material's recorded purchase price, in the material's currency.",
  "معلومةٌ مرجعية": "Reference figure",
  "— لا تدخل المصاريف ولا صافي الربح (المشتريات تدخلها حين تُسجَّل مصروفاً). الرقمُ نفسُه الذي تعرضه صفحة المحاسبة للفترة.": "— it doesn't enter expenses or net profit (purchases do when recorded as an expense). It's the same figure the accounting page shows for the period.",
  "التفصيل حسب": "Break down by",
  "= إنتاج الطبيب ناقص تكلفة مخابره. تُطرح التكلفة أولاً ثم تُحسب نسبتُه من الباقي، فيتقاسم مع العيادة كلفةَ المخبر.": "= the dentist's production minus their lab cost. The cost is taken off first, then their share is calculated on the rest, so they share the lab cost with the clinic.",
  "الأعدل للعيادة.": "The fairest for the clinic.",
  "مستحق الطبيب = نسبته × (الإنتاج − تكلفة المخبر)": "Dentist's earnings = their share × (production − lab cost)",
  "= ما قُبض فعلاً من المرضى مقابل جلسات هذا الطبيب. نسبتُه تُحسب على المقبوض لا على المسجَّل، فلا يأخذ حصّةً عن مبلغٍ لم يدخل الصندوق بعد.": "= what was actually collected from patients for this dentist's sessions. Their share is on what was collected, not what was recorded, so they don't take a share of money that hasn't come in yet.",
